-- V2 : 상속 A형·C형 물리 변환 저장 구조 (M-7 상속 A·C, 2026-11-22 — docs/completed/inheritance-strategy-ac-m7.md, 확정 정책 D-AC-01~18)
-- ① TB_SBTYP_GROUP_CNVR (서브타입 그룹 변환) : 상속 그룹마다 0~1행. A형(SINGLE_TABLE)은 통합 테이블·분류 컬럼이 반드시 있고, C형(TABLE_PER_CONCRETE)은 둘 다 없다
--   (CK_SBTYP_GROUP_CNVR_02). 행이 없는 그룹은 B형(엔터티마다 테이블) 또는 아직 만들지 않은 그룹이다 — 기존 데이터에 행을 만들지 않는다 (예전 B형을 기록으로 추정하지 않는다).
--   한 상속 계층의 그룹이 모두 같은 전략인지·통합 테이블이 하나인지·분류 컬럼이 그룹 분류 속성의 매핑 컬럼인지는 서비스가 논리 모델 행 잠금 안에서 검사한다 (DB 로 표현할 수 없다).
-- ② TB_SBTYP_ATRB_COL_MPNG (서브타입 속성 컬럼 매핑) : C형 말단 테이블의 복제 컬럼 ↔ 조상 일반 속성 (원본 속성 ID). 같은 원본 속성을 여러 말단이 각각 쓰므로
--   (엔터티 테이블 매핑, 원본 속성)·컬럼을 각각 UNIQUE 로 둔다 (서브타입 식별자 컬럼 매핑과 같은 꼴). 기존 매핑 테이블과 UNIQUE 는 바꾸지 않는다 (D-AC-02 — 완화 없음).
--   컬럼이 속성 컬럼 매핑·서브타입 식별자 컬럼 매핑과 겹치지 않는 것(교차 중복)과 원본 속성이 실제 조상의 일반 속성인 것은 서비스가 검사한다.
-- 이름 (표준 사전 확인 2026-11-22) : 서브타입(SBTYP)·그룹(GROUP)·유형(TYPE)·코드(CD)·분류(CLSF)·속성(ATRB)·컬럼(COL)·매핑(MPNG)·일련번호(SN) 는 예제 사전에 있고,
--   새 단어는 변환(CNVR, 공통표준단어) 하나, 새 용어는 4개다. 예제(프로젝트 0)에 단어 → 용어 → 물리 → 논리 → 매핑 → 관계(+ 속성 짝) → 제약조건 → 인덱스 → 업무 설명 순서로 넣는다.
-- V0·V1 은 바꾸지 않는다. 기존 행을 바꾸거나 지우지 않는다.

create sequence SQ_SBTYP_GROUP_CNVR start with 1 increment by 50;
create table TB_SBTYP_GROUP_CNVR (
    SBTYP_GROUP_CNVR_SN bigint not null,
    PRJ_SN bigint not null,
    LGCL_SBTYP_GROUP_SN bigint not null,
    CNVR_TYPE_CD varchar(20) not null,
    TBL_SN bigint,
    CLSF_COL_SN bigint,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_SBTYP_GROUP_CNVR primary key (SBTYP_GROUP_CNVR_SN)
);
create unique index UX_SBTYP_GROUP_CNVR_01 on TB_SBTYP_GROUP_CNVR (LGCL_SBTYP_GROUP_SN);
create index IX_SBTYP_GROUP_CNVR_01 on TB_SBTYP_GROUP_CNVR (PRJ_SN);
create index IX_SBTYP_GROUP_CNVR_02 on TB_SBTYP_GROUP_CNVR (TBL_SN);
create index IX_SBTYP_GROUP_CNVR_03 on TB_SBTYP_GROUP_CNVR (CLSF_COL_SN);
alter table TB_SBTYP_GROUP_CNVR add constraint FK_SBTYP_GROUP_CNVR_01 foreign key (LGCL_SBTYP_GROUP_SN) references TB_LGCL_SBTYP_GROUP;
alter table TB_SBTYP_GROUP_CNVR add constraint FK_SBTYP_GROUP_CNVR_02 foreign key (TBL_SN) references TB_TBL;
alter table TB_SBTYP_GROUP_CNVR add constraint FK_SBTYP_GROUP_CNVR_03 foreign key (CLSF_COL_SN) references TB_COL;

create sequence SQ_SBTYP_ATRB_COL_MPNG start with 1 increment by 50;
create table TB_SBTYP_ATRB_COL_MPNG (
    SBTYP_ATRB_COL_MPNG_SN bigint not null,
    ENTT_TBL_MPNG_SN bigint not null,
    LGCL_ATRB_SN bigint not null,
    COL_SN bigint not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_SBTYP_ATRB_COL_MPNG primary key (SBTYP_ATRB_COL_MPNG_SN)
);
create unique index UX_SBTYP_ATRB_COL_MPNG_01 on TB_SBTYP_ATRB_COL_MPNG (ENTT_TBL_MPNG_SN, LGCL_ATRB_SN);
create unique index UX_SBTYP_ATRB_COL_MPNG_02 on TB_SBTYP_ATRB_COL_MPNG (COL_SN);
create index IX_SBTYP_ATRB_COL_MPNG_01 on TB_SBTYP_ATRB_COL_MPNG (LGCL_ATRB_SN);
alter table TB_SBTYP_ATRB_COL_MPNG add constraint FK_SBTYP_ATRB_COL_MPNG_01 foreign key (ENTT_TBL_MPNG_SN) references TB_ENTT_TBL_MPNG;
alter table TB_SBTYP_ATRB_COL_MPNG add constraint FK_SBTYP_ATRB_COL_MPNG_02 foreign key (LGCL_ATRB_SN) references TB_LGCL_ATRB;
alter table TB_SBTYP_ATRB_COL_MPNG add constraint FK_SBTYP_ATRB_COL_MPNG_03 foreign key (COL_SN) references TB_COL;

alter table TB_SBTYP_GROUP_CNVR add constraint CK_SBTYP_GROUP_CNVR_01 check (CNVR_TYPE_CD in ('SINGLE_TABLE', 'TABLE_PER_CONCRETE'));
alter table TB_SBTYP_GROUP_CNVR add constraint CK_SBTYP_GROUP_CNVR_02 check ((CNVR_TYPE_CD = 'SINGLE_TABLE' and TBL_SN is not null and CLSF_COL_SN is not null)
    or (CNVR_TYPE_CD = 'TABLE_PER_CONCRETE' and TBL_SN is null and CLSF_COL_SN is null));

comment on table TB_SBTYP_GROUP_CNVR is '서브타입 그룹 변환';
comment on column TB_SBTYP_GROUP_CNVR.SBTYP_GROUP_CNVR_SN is '서브타입 그룹 변환 일련번호';
comment on column TB_SBTYP_GROUP_CNVR.PRJ_SN is '프로젝트 일련번호';
comment on column TB_SBTYP_GROUP_CNVR.LGCL_SBTYP_GROUP_SN is '논리 서브타입 그룹 일련번호';
comment on column TB_SBTYP_GROUP_CNVR.CNVR_TYPE_CD is '변환 유형 코드';
comment on column TB_SBTYP_GROUP_CNVR.TBL_SN is '테이블 일련번호';
comment on column TB_SBTYP_GROUP_CNVR.CLSF_COL_SN is '분류 컬럼 일련번호';
comment on column TB_SBTYP_GROUP_CNVR.REG_DT is '등록 일시';
comment on column TB_SBTYP_GROUP_CNVR.MDFCN_DT is '수정 일시';
comment on column TB_SBTYP_GROUP_CNVR.RGTR_ID is '등록자 아이디';
comment on column TB_SBTYP_GROUP_CNVR.MDFR_ID is '수정자 아이디';

comment on table TB_SBTYP_ATRB_COL_MPNG is '서브타입 속성 컬럼 매핑';
comment on column TB_SBTYP_ATRB_COL_MPNG.SBTYP_ATRB_COL_MPNG_SN is '서브타입 속성 컬럼 매핑 일련번호';
comment on column TB_SBTYP_ATRB_COL_MPNG.ENTT_TBL_MPNG_SN is '엔터티 테이블 매핑 일련번호';
comment on column TB_SBTYP_ATRB_COL_MPNG.LGCL_ATRB_SN is '논리 속성 일련번호';
comment on column TB_SBTYP_ATRB_COL_MPNG.COL_SN is '컬럼 일련번호';
comment on column TB_SBTYP_ATRB_COL_MPNG.REG_DT is '등록 일시';
comment on column TB_SBTYP_ATRB_COL_MPNG.MDFCN_DT is '수정 일시';
comment on column TB_SBTYP_ATRB_COL_MPNG.RGTR_ID is '등록자 아이디';
comment on column TB_SBTYP_ATRB_COL_MPNG.MDFR_ID is '수정자 아이디';

-- ---------- 예제 : 데이터 사전 (새 단어 1개 · 새 용어 4개 — 나머지 단어·용어는 있다) ----------

-- ---------- 예제 : 물리 모델 TB_SBTYP_GROUP_CNVR ----------
-- ---------- 예제 : 논리 모델 서브타입 그룹 변환 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 서브타입 그룹 변환 ----------
-- ---------- 예제 : 관계 (FK 마다 물리 관계 + 논리 관계 + 속성 짝) 서브타입 그룹 변환 ----------
-- ---------- 예제 : CHECK 제약조건 서브타입 그룹 변환 ----------
-- ---------- 예제 : 인덱스 서브타입 그룹 변환 (V2 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 서브타입 그룹 변환 ----------
update TB_TBL set TASK_EXPLN = '상속 그룹을 어떤 물리 구조로 만들었는지 기록한다 (M-7 상속 A·C형, D-AC-02). A형은 계층 전체를 루트 테이블 하나에 통합하고 그 테이블과 그룹의 분류 속성 컬럼을, C형은 말단 서브타입마다 테이블을 만들고 테이블·분류 컬럼 없이 전략만 둔다. 한 상속 계층의 그룹은 모두 같은 전략이어야 한다 (서비스가 논리 모델 행 잠금 안에서 검사). 관련 매핑이 남아 있으면 지울 수 없다 (D-AC-18). 물리 테이블·컬럼을 바꾸지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '서브타입 그룹 변환 기록을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'SBTYP_GROUP_CNVR_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '기록이 속한 프로젝트 (프로젝트 격리·프로젝트 삭제 정리).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '변환한 상속 그룹. 그룹 하나에 기록 하나다. 기록이 있는 그룹은 지울 수 없다 (기록을 먼저 지운다).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'LGCL_SBTYP_GROUP_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = 'SINGLE_TABLE(A형) 또는 TABLE_PER_CONCRETE(C형).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'CNVR_TYPE_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = 'A형의 통합 테이블 (루트 엔터티가 직접 매핑된 테이블). C형은 비어 있어야 한다.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'TBL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = 'A형에서 그룹의 분류 속성이 매핑된 통합 테이블 컬럼. C형은 비어 있어야 한다.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'CLSF_COL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_GROUP_CNVR' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;

-- ---------- 예제 : 물리 모델 TB_SBTYP_ATRB_COL_MPNG ----------
-- ---------- 예제 : 논리 모델 서브타입 속성 컬럼 매핑 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 서브타입 속성 컬럼 매핑 ----------
-- ---------- 예제 : 관계 (FK 마다 물리 관계 + 논리 관계 + 속성 짝) 서브타입 속성 컬럼 매핑 ----------
-- ---------- 예제 : 인덱스 서브타입 속성 컬럼 매핑 (V2 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 서브타입 속성 컬럼 매핑 ----------
update TB_TBL set TASK_EXPLN = 'C형(말단 서브타입별 테이블)에서 말단 테이블에 복제한 조상(루트·중간 엔터티)의 일반 속성이 어느 원본 속성에서 왔는지 말단 엔터티 매핑 문맥으로 연결한다 (M-7 상속 C형, D-AC-02). 상속 PK 는 서브타입 식별자 컬럼 매핑에, 말단 자체 속성은 속성 컬럼 매핑에 두고 여기에는 넣지 않는다. 연결만 저장하며 물리 컬럼을 바꾸지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '서브타입 속성 컬럼 매핑을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'SBTYP_ATRB_COL_MPNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '말단 서브타입 엔터티와 그 물리 테이블의 매핑 (문맥). 이 매핑을 해제하려면 서브타입 속성 컬럼 매핑을 먼저 해제한다.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'ENTT_TBL_MPNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '복제한 원본 = 조상 엔터티의 일반 속성 (주 식별자 속성은 넣지 않는다). 같은 매핑 안에서는 한 번만 쓴다.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'LGCL_ATRB_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '말단 테이블의 복제 컬럼. 컬럼 하나는 한 매핑에만 쓰이며 속성 컬럼 매핑·서브타입 식별자 컬럼 매핑에 쓰인 컬럼은 쓸 수 없다.' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'COL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;

