insert into TB_ENTT_TBL_MPNG(ENTT_TBL_MPNG_SN, PRJ_SN, LGCL_ENTT_SN, TBL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_ENTT_TBL_MPNG, 0, e.LGCL_ENTT_SN, t.TBL_SN, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e join TB_LGCL_MDL m on m.LGCL_MDL_SN = e.LGCL_MDL_SN and m.PRJ_SN = 0 and m.MDL_NM = 'LEXORMA' join TB_TBL t on t.PRJ_SN = 0 and t.TBL_NM = 'TB_SBTYP_GROUP_CNVR' where e.PRJ_SN = 0 and e.ENTT_NM = '서브타입 그룹 변환' and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.LGCL_ENTT_SN = e.LGCL_ENTT_SN) and not exists (select 1 from TB_ENTT_TBL_MPNG x where x.TBL_SN = t.TBL_SN);
