insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD) select next value for SQ_TBL_IDX_COL, i.IDX_SN, c.COL_SN, 1 from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'UX_SBTYP_ATRB_COL_MPNG_02' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'COL_SN' where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_ORD = 1);
insert into TB_TBL_IDX(IDX_SN, PRJ_SN, TBL_SN, IDX_NM, IDX_TYPE_NM, UNQ_YN, APRV_YN, IDX_SRC_CD, DRVN_COL_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_TBL_IDX, 0, t.TBL_SN, 'IX_SBTYP_ATRB_COL_MPNG_01', null, false, true, 'USER', null, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_TBL t where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and not exists (select 1 from TB_TBL_IDX i where i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_SBTYP_ATRB_COL_MPNG_01');
insert into TB_TBL_IDX_COL(IDX_COL_SN, IDX_SN, COL_SN, COL_ORD) select next value for SQ_TBL_IDX_COL, i.IDX_SN, c.COL_SN, 1 from TB_TBL t join TB_TBL_IDX i on i.TBL_SN = t.TBL_SN and i.IDX_NM = 'IX_SBTYP_ATRB_COL_MPNG_01' join TB_COL c on c.TBL_SN = t.TBL_SN and c.COL_NM = 'LGCL_ATRB_SN' where t.PRJ_SN = 0 and t.TBL_NM = 'TB_SBTYP_ATRB_COL_MPNG' and not exists (select 1 from TB_TBL_IDX_COL x where x.IDX_SN = i.IDX_SN and x.COL_ORD = 1);
